CREATE OR REPLACE FUNCTION public.has_clinic_role(c uuid, medical boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(auth.jwt()->>'aal','')='aal2' AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND clinic_id=c AND (NOT medical OR role='doctor')) $$;
CREATE FUNCTION public.clinic_doctors(c uuid) RETURNS TABLE(user_id uuid, display_name text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_clinic_role(c) THEN RAISE EXCEPTION 'Acesso negado'; END IF; RETURN QUERY SELECT r.user_id,coalesce(nullif(p.display_name,''),'Médico autorizado') FROM public.user_roles r LEFT JOIN public.profiles p ON p.id=r.user_id WHERE r.clinic_id=c AND r.role='doctor' ORDER BY r.user_id; END $$;
REVOKE ALL ON FUNCTION public.clinic_doctors(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.clinic_doctors(uuid) TO authenticated;
CREATE UNIQUE INDEX encounters_one_per_appointment ON public.encounters(appointment_id) WHERE appointment_id IS NOT NULL;
CREATE FUNCTION public.validate_appointment_doctor() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE linked public.encounters; BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE clinic_id=new.clinic_id AND user_id=new.professional_id AND role='doctor') THEN RAISE EXCEPTION 'Selecione um médico autorizado da clínica'; END IF; IF TG_OP='UPDATE' THEN IF new.clinic_id<>old.clinic_id THEN RAISE EXCEPTION 'Clínica imutável'; END IF; SELECT * INTO linked FROM public.encounters WHERE appointment_id=old.id; IF FOUND AND (new.patient_id IS DISTINCT FROM old.patient_id OR new.professional_id<>old.professional_id OR new.is_block OR new.status<>CASE WHEN linked.status='finalizado' THEN 'realizado' ELSE 'em atendimento' END) THEN RAISE EXCEPTION 'Consulta vinculada: paciente, profissional e estado devem preservar o atendimento'; END IF; END IF; IF new.status IN ('em atendimento','realizado') AND NOT EXISTS(SELECT 1 FROM public.encounters WHERE appointment_id=new.id AND status=CASE WHEN new.status='realizado' THEN 'finalizado' ELSE 'rascunho' END) THEN RAISE EXCEPTION 'Estado exige atendimento correspondente'; END IF; RETURN new; END $$;
CREATE TRIGGER appointments_authorized_doctor BEFORE INSERT OR UPDATE ON public.appointments FOR EACH ROW EXECUTE FUNCTION public.validate_appointment_doctor();
CREATE FUNCTION public.validate_encounter_link() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.appointments; BEGIN IF new.appointment_id IS NOT NULL THEN SELECT * INTO a FROM public.appointments WHERE id=new.appointment_id AND clinic_id=new.clinic_id FOR UPDATE; IF NOT FOUND OR a.patient_id IS DISTINCT FROM new.patient_id OR a.professional_id<>new.author_id OR a.is_block OR a.status IN ('cancelado','faltou','realizado') THEN RAISE EXCEPTION 'Consulta incompatível com atendimento'; END IF; END IF; RETURN new; END $$;
CREATE TRIGGER encounter_link_valid BEFORE INSERT ON public.encounters FOR EACH ROW EXECUTE FUNCTION public.validate_encounter_link();
CREATE FUNCTION public.sync_encounter_appointment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF new.appointment_id IS NOT NULL THEN UPDATE public.appointments SET status=CASE WHEN new.status='finalizado' THEN 'realizado' ELSE 'em atendimento' END WHERE id=new.appointment_id AND clinic_id=new.clinic_id; END IF; RETURN new; END $$;
CREATE TRIGGER sync_encounter_appointment AFTER INSERT OR UPDATE ON public.encounters FOR EACH ROW EXECUTE FUNCTION public.sync_encounter_appointment();
CREATE TABLE public.clinical_attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES public.clinics(id),patient_id uuid NOT NULL,encounter_id uuid,author_id uuid NOT NULL DEFAULT auth.uid(),storage_path text NOT NULL UNIQUE,filename text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(clinic_id,patient_id) REFERENCES public.patients(clinic_id,id),FOREIGN KEY(clinic_id,encounter_id) REFERENCES public.encounters(clinic_id,id));
GRANT SELECT,INSERT ON public.clinical_attachments TO authenticated; GRANT ALL ON public.clinical_attachments TO service_role; ALTER TABLE public.clinical_attachments ENABLE ROW LEVEL SECURITY;
CREATE POLICY attachments_read ON public.clinical_attachments FOR SELECT TO authenticated USING(public.has_clinic_role(clinic_id,true)); CREATE POLICY attachments_insert ON public.clinical_attachments FOR INSERT TO authenticated WITH CHECK(public.has_clinic_role(clinic_id,true) AND author_id=auth.uid() AND split_part(storage_path,'/',1)=clinic_id::text AND (encounter_id IS NULL OR EXISTS(SELECT 1 FROM public.encounters e WHERE e.id=encounter_id AND e.clinic_id=clinical_attachments.clinic_id AND e.patient_id=clinical_attachments.patient_id)));
CREATE TRIGGER audit_attachments AFTER INSERT ON public.clinical_attachments FOR EACH ROW EXECUTE FUNCTION public.audit_change();
CREATE FUNCTION public.validate_document_path() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF new.storage_path IS NOT NULL AND split_part(new.storage_path,'/',1)<>new.clinic_id::text THEN RAISE EXCEPTION 'Arquivo de outra clínica'; END IF; RETURN new; END $$; CREATE TRIGGER documents_path BEFORE INSERT ON public.documents FOR EACH ROW EXECUTE FUNCTION public.validate_document_path();
REVOKE SELECT ON public.encounters,public.encounter_versions,public.addenda,public.documents FROM authenticated;
GRANT SELECT(id,clinic_id,patient_id,appointment_id,author_id,modality,status,version,created_at,updated_at,finalized_at) ON public.encounters TO authenticated;
GRANT SELECT(id,clinic_id,patient_id,author_id,kind,status,storage_path,created_at) ON public.documents TO authenticated;
CREATE FUNCTION public.clinical_read(c uuid, entity uuid, mode text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p uuid; result jsonb; BEGIN IF NOT public.has_clinic_role(c,true) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
IF mode='encounter' THEN SELECT patient_id INTO p FROM public.encounters WHERE id=entity AND clinic_id=c; IF p IS NULL THEN RAISE EXCEPTION 'Registro indisponível'; END IF; SELECT jsonb_build_object('encounter',to_jsonb(e),'versions',coalesce((SELECT jsonb_agg(v ORDER BY v.version) FROM public.encounter_versions v WHERE v.clinic_id=c AND v.encounter_id=e.id),'[]'::jsonb),'addenda',coalesce((SELECT jsonb_agg(a ORDER BY a.created_at,a.id) FROM public.addenda a WHERE a.clinic_id=c AND a.encounter_id=e.id),'[]'::jsonb),'attachments',coalesce((SELECT jsonb_agg(a ORDER BY a.created_at,a.id) FROM public.clinical_attachments a WHERE a.clinic_id=c AND a.encounter_id=e.id),'[]'::jsonb)) INTO result FROM public.encounters e WHERE e.id=entity AND e.clinic_id=c;
ELSIF mode='document' THEN SELECT to_jsonb(d) INTO result FROM public.documents d WHERE d.id=entity AND d.clinic_id=c; IF result IS NULL THEN RAISE EXCEPTION 'Registro indisponível'; END IF;
ELSIF mode IN ('patient','export') THEN IF NOT EXISTS(SELECT 1 FROM public.patients WHERE id=entity AND clinic_id=c) THEN RAISE EXCEPTION 'Paciente indisponível'; END IF; SELECT jsonb_build_object('patient',(SELECT to_jsonb(p) FROM public.patients p WHERE p.id=entity AND p.clinic_id=c),'appointments',coalesce((SELECT jsonb_agg(a ORDER BY a.starts_at,a.id) FROM public.appointments a WHERE a.clinic_id=c AND a.patient_id=entity),'[]'::jsonb),'encounters',coalesce((SELECT jsonb_agg(e ORDER BY e.created_at,e.id) FROM public.encounters e WHERE e.clinic_id=c AND e.patient_id=entity),'[]'::jsonb),'versions',coalesce((SELECT jsonb_agg(v ORDER BY v.created_at,v.id) FROM public.encounter_versions v JOIN public.encounters e ON e.id=v.encounter_id AND e.clinic_id=v.clinic_id WHERE v.clinic_id=c AND e.patient_id=entity),'[]'::jsonb),'addenda',coalesce((SELECT jsonb_agg(a ORDER BY a.created_at,a.id) FROM public.addenda a JOIN public.encounters e ON e.id=a.encounter_id AND e.clinic_id=a.clinic_id WHERE a.clinic_id=c AND e.patient_id=entity),'[]'::jsonb),'documents',coalesce((SELECT jsonb_agg(d ORDER BY d.created_at,d.id) FROM public.documents d WHERE d.clinic_id=c AND d.patient_id=entity),'[]'::jsonb),'attachments',coalesce((SELECT jsonb_agg(a ORDER BY a.created_at,a.id) FROM public.clinical_attachments a WHERE a.clinic_id=c AND a.patient_id=entity),'[]'::jsonb)) INTO result;
ELSE RAISE EXCEPTION 'Operação inválida'; END IF;
INSERT INTO public.audit_events(clinic_id,actor,event,entity_id,metadata) VALUES(c,auth.uid(),'read:'||mode,entity,jsonb_build_object('scope',mode)); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.clinical_read(uuid,uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.clinical_read(uuid,uuid,text) TO authenticated;
CREATE FUNCTION public.save_clinical(c uuid, entity uuid, expected integer, body jsonb, finalize boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.encounters; BEGIN IF NOT public.has_clinic_role(c,true) THEN RAISE EXCEPTION 'Acesso negado'; END IF; SELECT * INTO e FROM public.encounters WHERE id=entity AND clinic_id=c AND author_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Acesso negado'; END IF; IF e.version<>expected THEN RETURN jsonb_build_object('conflict',true); END IF; UPDATE public.encounters SET content=body,version=expected+1,status=CASE WHEN finalize THEN 'finalizado' ELSE 'rascunho' END WHERE id=entity RETURNING * INTO e; RETURN jsonb_build_object('encounter',to_jsonb(e)); END $$;
REVOKE ALL ON FUNCTION public.save_clinical(uuid,uuid,integer,jsonb,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.save_clinical(uuid,uuid,integer,jsonb,boolean) TO authenticated;
CREATE FUNCTION public.audited_file_read(path text) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; entity uuid; BEGIN SELECT clinic_id,id INTO c,entity FROM public.documents WHERE storage_path=path; IF c IS NULL THEN SELECT clinic_id,id INTO c,entity FROM public.clinical_attachments WHERE storage_path=path; END IF; IF c IS NULL OR NOT public.has_clinic_role(c,true) THEN RETURN false; END IF; INSERT INTO public.audit_events(clinic_id,actor,event,entity_id) VALUES(c,auth.uid(),'file_access',entity); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.audited_file_read(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.audited_file_read(text) TO authenticated;
ALTER POLICY clinical_files_read ON storage.objects USING(bucket_id='clinical-originals' AND public.audited_file_read(name));
CREATE INDEX patients_search_page ON public.patients(clinic_id,name,id); CREATE INDEX appointments_period_page ON public.appointments(clinic_id,starts_at,id); CREATE INDEX encounters_page ON public.encounters(clinic_id,created_at,id); CREATE INDEX documents_page ON public.documents(clinic_id,created_at,id);